import 'package:flutter/widgets.dart';

/// Supported app locales. The order here is also the order shown in the
/// language picker.
const List<Locale> kSupportedLocales = [
  Locale('en'),
  Locale('uk'),
  Locale('es'),
  Locale('fr'),
  Locale('de'),
  Locale('it'),
  Locale('pt'),
  Locale('ru'),
  Locale('zh'),
  Locale('ja'),
];

/// Display name for each supported language, in its own language.
const Map<String, String> kLanguageNames = {
  'en': 'English',
  'uk': 'Українська',
  'es': 'Español',
  'fr': 'Français',
  'de': 'Deutsch',
  'it': 'Italiano',
  'pt': 'Português',
  'ru': 'Русский',
  'zh': '中文',
  'ja': '日本語',
};

/// Resolves a locale string (`en`, `uk`, etc.) to a [Locale]. Falls back to
/// English if the code is unknown.
Locale localeFromCode(String? code) {
  if (code == null) return const Locale('en');
  for (final l in kSupportedLocales) {
    if (l.languageCode == code) return l;
  }
  return const Locale('en');
}

/// Localized string lookup. Use [S.of] to retrieve the instance for the
/// current locale and access individual keys via the named getters below.
class S {
  S(this.locale);

  final Locale locale;

  static S of(BuildContext context) {
    final locale = Localizations.maybeLocaleOf(context) ?? const Locale('en');
    assert(() {
      _debugReportMissingKeys();
      return true;
    }());
    return S(locale);
  }

  /// Visual-only override: when true, routine-feature strings are rewritten to
  /// say "Habit"/"Habits" (in the active language) instead of "Routine". Set
  /// from [SettingsController]; the underlying data model is unchanged.
  static bool useHabitNaming = false;

  String t(String key) {
    final table = _translations[locale.languageCode] ?? _translations['en']!;
    final value = table[key] ?? _translations['en']![key] ?? key;
    if (useHabitNaming && _habitNamingKeys.contains(key)) {
      return _applyHabitNaming(value, locale.languageCode);
    }
    return value;
  }

  /// Keys whose user-facing value mentions the "routine" concept and should be
  /// rewritten to "habit" wording when [useHabitNaming] is on.
  static const Set<String> _habitNamingKeys = {
    'tabRoutines',
    'appBadgeIncludeRoutines',
    'showRoutinesInToday',
    'showRoutinesInCalendar',
    'showPastRoutines',
    'showFutureRoutines',
    'showRoutinesHint',
    'sectionShowRoutines',
    'resetAllDataBody',
    'routineName',
    'newRoutine',
    'editRoutine',
    'overdueRoutineTitle',
    'recordManualInfo',
    'noRoutinesToday',
    'noRoutinesYet',
    'tapPlusFirstAdd',
    'tapPlusFirstCreate',
    'deleteRoutine',
  };

  /// Ordered (plural/uppercase before singular) word substitutions per locale.
  /// Locales whose tables already use habit wording (or where "routine" is
  /// invariant) are intentionally absent → no rewrite.
  static const Map<String, List<List<String>>> _habitSubstitutions = {
    'en': [
      ['Routines', 'Habits'],
      ['ROUTINES', 'HABITS'],
      ['routines', 'habits'],
      ['Routine', 'Habit'],
      ['routine', 'habit'],
    ],
    'es': [
      ['Rutinas', 'Hábitos'],
      ['RUTINAS', 'HÁBITOS'],
      ['rutinas', 'hábitos'],
      ['Rutina', 'Hábito'],
      ['rutina', 'hábito'],
    ],
    'fr': [
      ['Routines', 'Habitudes'],
      ['ROUTINES', 'HABITUDES'],
      ['routines', 'habitudes'],
      ['Routine', 'Habitude'],
      ['routine', 'habitude'],
    ],
    'de': [
      ['Routinen', 'Gewohnheiten'],
      ['ROUTINEN', 'GEWOHNHEITEN'],
      ['routinen', 'gewohnheiten'],
      ['Routine', 'Gewohnheit'],
      ['routine', 'Gewohnheit'],
    ],
    'pt': [
      ['Rotinas', 'Hábitos'],
      ['ROTINAS', 'HÁBITOS'],
      ['rotinas', 'hábitos'],
      ['Rotina', 'Hábito'],
      ['rotina', 'hábito'],
    ],
  };

  static String _applyHabitNaming(String value, String code) {
    final subs = _habitSubstitutions[code];
    if (subs == null) return value;
    var out = value;
    for (final pair in subs) {
      out = out.replaceAll(pair[0], pair[1]);
    }
    return out;
  }

  static bool _completenessChecked = false;

  /// Debug-only: logs any locale whose table is missing keys that exist in
  /// English. Such keys silently fall back to English at runtime (see [t]), so
  /// without this they slip past QA unnoticed. Runs once; no release-mode cost
  /// because the call site is wrapped in an `assert`.
  static void _debugReportMissingKeys() {
    if (_completenessChecked) return;
    _completenessChecked = true;
    final en = _translations['en']!;
    _translations.forEach((code, table) {
      if (code == 'en') return;
      final missing = en.keys.where((k) => !table.containsKey(k)).toList();
      if (missing.isNotEmpty) {
        debugPrint(
            '[i18n] "$code" missing ${missing.length} key(s): ${missing.join(', ')}');
      }
    });
  }

